(()=>{const h=__game.scene.getScene('Hub'); const solids=h.solids.getChildren().map(z=>z.body); const out={};
for(const sp of h.spots.filter(s=>s.id.startsWith('npc:'))){
  let reach=0; for(let a=0;a<16;a++){for(const r of [10,14,18]){const x=sp.x+Math.cos(a/16*Math.PI*2)*r, y=sp.y+Math.sin(a/16*Math.PI*2)*r;
    const blocked=solids.some(b=>x>b.x-5&&x<b.x+b.width+5&&y>b.y-5&&y<b.y+b.height+5); if(!blocked) reach++;}}
  const n=h.npcSprites.get(sp.id.slice(4)); const sb=n.sprite.getBounds();
  const occl=h.children.list.filter(o=>o!==n.sprite && o.type==='Sprite' && o.depth>n.sprite.depth && o.getBounds && Phaser.Geom.Rectangle.Overlaps(o.getBounds(),sb) && o.frame && String(o.frame.name).startsWith('p/house')).map(o=>o.frame.name);
  out[sp.id]={reach, occl};
} return JSON.stringify(out);})()
